window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-09d13e48bff876e8"]={"versions": [{"id": "FIG-09d13e48bff876e8", "releases": ["R1.3.0", "R17-03_R1.1.0", "R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd SEQ-LinkLossServer</code>) zur Spezifikation des SOME/IP-Service-Discovery-Protokolls (SOME/IP-SD) im AUTOSAR-Kontext. Das Diagramm modelliert das Publish/Subscribe-Verhalten und die Resynchronisation der Subskriptionen bei einem zwischenzeitlichen Verbindungsverlust (Link Loss) auf Seiten des Servers unter Abstraktion von konkreten Zeitabläufen (Timings).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält zwei primäre Kommunikationspartner (Lebenslinien):</p>\n<ul class=\"fig-list\"><li><code>Server</code>: Dienstanbieter, der SOME/IP-Services anbietet und Eventgruppen verwaltet.\n</li><li><code>Client</code>: Dienstnutzer und Abonnent von Eventgruppen.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\"><li>Netzwerkinteraktionen (SOME/IP-SD / SOME/IP):\n<ul class=\"fig-list\"><li><code>OfferService()</code>: Broadcast/Unicast des Servers zum Bekanntgeben eines Dienstes; im Wiederanlauf explizit annotiert mit Parametern <code>[Session ID=1, Reboot=1]</code>.\n</li><li><code>SubscribeEventgroup()</code>: Nachricht des Clients zur Registrierung für eine Eventgruppe.\n</li><li><code>SubscribeEventgroupAck + Events()</code>: Bestätigung der Subskription durch den Server inklusive nachfolgender/initialer Event-Daten.\n</li></ul>\n</li><li>Interne Ereignisse und Kontrollaufrufe (Self-Messages):\n<ul class=\"fig-list\"><li><code>updateRegistration()</code>: Lokale Aktualisierung/Eintragung der Client-Registrierung am Server.\n</li><li><code>linkDown()</code>: Lokales Ereignis bei Erkennung des Link-Ausfalls an der Server-Netzwerkschnittstelle.\n</li><li><code>deleteRegistrations()</code>: Bereinigung bzw. Verwerfen bestehender Client-Subskriptionen infolge des Verbindungsverlusts.\n</li><li><code>linkUp()</code>: Lokales Ereignis bei Wiederherstellung der Netzwerkverbindung am Server.\n</li></ul>\n</li><li>Notiz-Elemente:\n<ul class=\"fig-list\"><li><code>No registration.</code>: Initiale Zustandsbemerkung am Server.\n</li><li><code>Reboot detected!</code>: Statusbeobachtung am Client nach Empfang des erneuten <code>OfferService()</code> mit gesetztem Reboot-Flag.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialer Verbindungsaufbau und Subskription:</strong>\n<ul class=\"fig-list\"><li>Der Server startet im Zustand ohne Registrierungen (<code>No registration.</code>) und sendet <code>OfferService()</code>.\n</li><li>Der Client reagiert mit <code>SubscribeEventgroup()</code>.\n</li><li>Der Server verarbeitet die Subskription über den internen Aufruf <code>updateRegistration()</code> und antwortet mit <code>SubscribeEventgroupAck + Events()</code>.\n</li></ul>\n</li><li><strong>Link Loss und Statusbereinigung:</strong>\n<ul class=\"fig-list\"><li>Am Server tritt ein Verbindungsabbruch auf, signalisiert durch das interne Ereignis <code>linkDown()</code>.\n</li><li>Infolgedessen führt der Server intern <code>deleteRegistrations()</code> aus, wodurch alle aktiven Registrierungen verworfen werden.\n</li></ul>\n</li><li><strong>Wiederverbindung und Reboot-Signalisierung:</strong>\n<ul class=\"fig-list\"><li>Die Verbindung wird am Server über <code>linkUp()</code> wiederhergestellt.\n</li><li>Der Server sendet ein neues <code>OfferService()</code> mit <code>Session ID=1</code> und gesetztem Reboot-Flag (<code>Reboot=1</code>).\n</li></ul>\n</li><li><strong>Erkennung und Resubskription:</strong>\n<ul class=\"fig-list\"><li>Der Client erkennt den Server-Reboot (<code>Reboot detected!</code>).\n</li><li>Der Client sendet erneut eine <code>SubscribeEventgroup()</code>-Anfrage an den Server.\n</li><li>Der Server führt wiederum intern <code>updateRegistration()</code> aus und bestätigt das Abonnement mit <code>SubscribeEventgroupAck + Events()</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Reboot-Erkennung:</strong> Das Setzen von <code>Reboot=1</code> zusammen mit einer zurückgesetzten <code>Session ID=1</code> im SOME/IP-SD-Offer-Header signalisiert dem Client einen Neustart bzw. Statusverlust des Servers.\n</li><li><strong>Zustandsrücksetzung bei Link Loss:</strong> Bei Erkennung von <code>linkDown()</code> auf Server-Seite müssen bestehende Registrierungen (<code>deleteRegistrations()</code>) verworfen werden, da von einem Verlust des Session-Kontexts ausgegangen wird.\n</li><li><strong>Client-Reaktivität:</strong> Clients müssen das Reboot-Flag auswerten und bei zuvor aktiven Subskriptionen unmittelbar eine erneute Eventgruppen-Subskription (<code>SubscribeEventgroup()</code>) initiieren, um den Event-Empfang unterbrechungsfrei fortzusetzen bzw. wiederherzustellen.\n</li><li><strong>Timing-Abstraktion:</strong> Konkrete Delay-Timer (z. B. Request-Response-Delay, Initial-Delay-Phasen von SOME/IP-SD) sind in diesem Diagramm bewusst ausgeblendet und müssen gemäß den timingbezogenen SD-Anforderungen des Standards implementiert werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-1f72be531866b7c5", "releases": ["R1.5.1", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd SEQ-LinkLossServer</code>) zur Spezifikation des SOME/IP-Service-Discovery-Protokolls (SOME/IP-SD) im AUTOSAR-Kontext. Das Diagramm modelliert das Publish/Subscribe-Verhalten und die Resynchronisation der Subskriptionen bei einem zwischenzeitlichen Verbindungsverlust (Link Loss) auf Seiten des Servers unter Abstraktion von konkreten Zeitabläufen (Timings).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält zwei primäre Kommunikationspartner (Lebenslinien):</p>\n<ul class=\"fig-list\"><li><code>Server</code>: Dienstanbieter, der SOME/IP-Services anbietet und Eventgruppen verwaltet.\n</li><li><code>Client</code>: Dienstnutzer und Abonnent von Eventgruppen.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\"><li>Netzwerkinteraktionen (SOME/IP-SD / SOME/IP):\n<ul class=\"fig-list\"><li><code>OfferService()</code>: Broadcast/Unicast des Servers zum Bekanntgeben eines Dienstes; im Wiederanlauf explizit annotiert mit Parametern <code>[Session ID=1, Reboot=1]</code>.\n</li><li><code>SubscribeEventgroup()</code>: Nachricht des Clients zur Registrierung für eine Eventgruppe.\n</li><li><code>SubscribeEventgroupAck + Events()</code>: Bestätigung der Subskription durch den Server inklusive nachfolgender/initialer Event-Daten.\n</li></ul>\n</li><li>Interne Ereignisse und Kontrollaufrufe (Self-Messages):\n<ul class=\"fig-list\"><li><code>updateRegistration()</code>: Lokale Aktualisierung/Eintragung der Client-Registrierung am Server.\n</li><li><code>linkDown()</code>: Lokales Ereignis bei Erkennung des Link-Ausfalls an der Server-Netzwerkschnittstelle.\n</li><li><code>deleteRegistrations()</code>: Bereinigung bzw. Verwerfen bestehender Client-Subskriptionen infolge des Verbindungsverlusts.\n</li><li><code>linkUp()</code>: Lokales Ereignis bei Wiederherstellung der Netzwerkverbindung am Server.\n</li></ul>\n</li><li>Notiz-Elemente:\n<ul class=\"fig-list\"><li><code>No registration.</code>: Initiale Zustandsbemerkung am Server.\n</li><li><code>Reboot detected!</code>: Statusbeobachtung am Client nach Empfang des erneuten <code>OfferService()</code> mit gesetztem Reboot-Flag.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Initialer Verbindungsaufbau und Subskription:</strong>\n<ul class=\"fig-list\"><li>Der Server startet im Zustand ohne Registrierungen (<code>No registration.</code>) und sendet <code>OfferService()</code>.\n</li><li>Der Client reagiert mit <code>SubscribeEventgroup()</code>.\n</li><li>Der Server verarbeitet die Subskription über den internen Aufruf <code>updateRegistration()</code> und antwortet mit <code>SubscribeEventgroupAck + Events()</code>.\n</li></ul>\n</li><li><strong>Link Loss und Statusbereinigung:</strong>\n<ul class=\"fig-list\"><li>Am Server tritt ein Verbindungsabbruch auf, signalisiert durch das interne Ereignis <code>linkDown()</code>.\n</li><li>Infolgedessen führt der Server intern <code>deleteRegistrations()</code> aus, wodurch alle aktiven Registrierungen verworfen werden.\n</li></ul>\n</li><li><strong>Wiederverbindung und Reboot-Signalisierung:</strong>\n<ul class=\"fig-list\"><li>Die Verbindung wird am Server über <code>linkUp()</code> wiederhergestellt.\n</li><li>Der Server sendet ein neues <code>OfferService()</code> mit <code>Session ID=1</code> und gesetztem Reboot-Flag (<code>Reboot=1</code>).\n</li></ul>\n</li><li><strong>Erkennung und Resubskription:</strong>\n<ul class=\"fig-list\"><li>Der Client erkennt den Server-Reboot (<code>Reboot detected!</code>).\n</li><li>Der Client sendet erneut eine <code>SubscribeEventgroup()</code>-Anfrage an den Server.\n</li><li>Der Server führt wiederum intern <code>updateRegistration()</code> aus und bestätigt das Abonnement mit <code>SubscribeEventgroupAck + Events()</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Reboot-Erkennung:</strong> Das Setzen von <code>Reboot=1</code> zusammen mit einer zurückgesetzten <code>Session ID=1</code> im SOME/IP-SD-Offer-Header signalisiert dem Client einen Neustart bzw. Statusverlust des Servers.\n</li><li><strong>Zustandsrücksetzung bei Link Loss:</strong> Bei Erkennung von <code>linkDown()</code> auf Server-Seite müssen bestehende Registrierungen (<code>deleteRegistrations()</code>) verworfen werden, da von einem Verlust des Session-Kontexts ausgegangen wird.\n</li><li><strong>Client-Reaktivität:</strong> Clients müssen das Reboot-Flag auswerten und bei zuvor aktiven Subskriptionen unmittelbar eine erneute Eventgruppen-Subskription (<code>SubscribeEventgroup()</code>) initiieren, um den Event-Empfang unterbrechungsfrei fortzusetzen bzw. wiederherzustellen.\n</li><li><strong>Timing-Abstraktion:</strong> Konkrete Delay-Timer (z. B. Request-Response-Delay, Initial-Delay-Phasen von SOME/IP-SD) sind in diesem Diagramm bewusst ausgeblendet und müssen gemäß den timingbezogenen SD-Anforderungen des Standards implementiert werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-09d13e48bff876e8", "to": "FIG-1f72be531866b7c5", "fr": "R1.3.0", "tr": "R1.5.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-1f72be531866b7c5", "to": "FIG-09d13e48bff876e8", "fr": "R1.5.1", "tr": "R17-03_R1.1.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
